package com.circlenet.domain.finance;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="financial_transactions") public class FinancialTransactionEntity{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="user_id",nullable=false) Long userId;@Column(nullable=false,precision=15,scale=2) BigDecimal amount;@Column(nullable=false,length=12) String direction;@Column(nullable=false,length=32) String category;@Column(length=160) String merchant;@Column(length=500) String description;@Column(name="occurred_at",nullable=false) Instant occurredAt;@Column(nullable=false,length=20) String source;@Column(name="source_fingerprint",length=64) String sourceFingerprint;@Column(name="created_at",nullable=false) Instant createdAt=Instant.now();
 public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public String getDirection(){return direction;}public void setDirection(String v){direction=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getMerchant(){return merchant;}public void setMerchant(String v){merchant=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Instant getOccurredAt(){return occurredAt;}public void setOccurredAt(Instant v){occurredAt=v;}public String getSource(){return source;}public void setSource(String v){source=v;}public String getSourceFingerprint(){return sourceFingerprint;}public void setSourceFingerprint(String v){sourceFingerprint=v;}public Instant getCreatedAt(){return createdAt;}
}

